							}
							AND = {
								exists = event_target:smear_option_3
								is_same_value = event_target:smear_option_3
							}
							has_country_flag = smear_campaign_recipient@root
						}
					}
					if = {
						limit = { NOT = { exists = event_target:smear_option_1 } }
